function results = dafc(T, c, alpha, opts)
%VFC.DAFC  Allotments among c fuzzy clusters at one threshold (one level of D-AFC(c)).
%
%   RESULTS = vfc.dafc(T, C, ALPHA)
%   RESULTS = vfc.dafc(T, C, ALPHA, OPTS)
%
%   Constructs all allotments among exactly C fuzzy clusters generated by the
%   fuzzy tolerance T at the level ALPHA (step 4 of the D-AFC(c)-algorithm).
%   A fuzzy cluster is the ALPHA-neighbourhood of its typical point:
%       C_l = { j : T(tau_l, j) >= alpha }.
%   C typical points form an allotment when
%     (1) coverage   : the union of the clusters is {1,...,n};
%     (2) separation : at most OPTS.max_intersections objects belong to more
%                      than one cluster (0 = fully separated clusters), and no
%                      typical point lies in another cluster;
%     (3) power      : opts.min_power <= |C_l| <= opts.max_power.
%
%   For the complete algorithm (all levels, automatic relaxation of the
%   separation condition) use vfc.dafc_c.
%
%   OPTS fields (all optional):
%     max_intersections - largest number w of objects in intersection areas
%                         [default: 0]; Inf drops the separation condition
%     min_power         - least number of objects in a cluster   [default: 1]
%     max_power         - largest number, 0 = no bound            [default: 0]
%     max_results       - number of allotments returned           [default: 200]
%     criterion         - 'F1' or 'F2'                            [default: 'F1']
%
%   Output RESULTS: 1-by-K struct array, best first:
%     .centers    - typical points (1-based object indices, ascending)
%     .clusters   - cell array of the member index vectors
%     .alpha      - the threshold
%     .c          - number of clusters
%     .score      - value of the criterion
%     .criterion  - criterion name
%     .membership - n-by-c matrix, U(j,l) = T(tau_l, j) for j in C_l, else 0
%     .labels     - n-by-1 hard assignment (cluster of the largest membership)
%     .intersections - number of objects in more than one cluster
%
%   F1 = sum_l mean_{j in C_l} T(tau_l, j) - alpha * c
%   F2 = mean_l mean_{j in C_l} T(tau_l, j)
%
%   Reference:
%     Viattchenin, D.A. A Heuristic Approach to Possibilistic Clustering.
%     Springer, 2013 (StudFuzz 297), sec. 2.2.1.
%
%   See also: vfc.dafc_c, vfc.dpafc, vfc.build_tolerance_matrix

    narginchk(3, 4);
    if nargin < 4, opts = struct(); end
    opts = defaults(opts);

    validateattributes(T,     {'numeric'}, {'square','2d','real','>=',0,'<=',1}, 'vfc.dafc', 'T', 1);
    validateattributes(c,     {'numeric'}, {'scalar','integer','positive'},       'vfc.dafc', 'c', 2);
    validateattributes(alpha, {'numeric'}, {'scalar','real','>',0,'<=',1},        'vfc.dafc', 'alpha', 3);

    n = size(T, 1);
    results = vfc.empty_results();
    if c > n, return; end

    w = opts.max_intersections;
    max_pow = opts.max_power;
    if max_pow == 0, max_pow = n; end

    N = T >= alpha;                       % N(i,:) = alpha-neighbourhood of object i
    powers = sum(N, 2)';
    candidates = find(powers >= opts.min_power & powers <= max_pow);
    if numel(candidates) < c, return; end

    % the sum of the cluster powers lies in [n, n + (c-1)*w]
    if isinf(w)
        max_sum = Inf;
    else
        max_sum = n + (c - 1) * w;
    end
    suffix_max = fliplr(cummax(fliplr(powers(candidates))));

    found_centers = zeros(0, c);
    chosen = zeros(1, c);
    search(1, 1, zeros(1, n), 0);

    if isempty(found_centers), return; end

    K = size(found_centers, 1);
    buf = cell(K, 1);
    for k = 1 : K
        ctrs = found_centers(k, :);
        clusters = arrayfun(@(t) find(N(t, :)), ctrs, 'UniformOutput', false);
        entry = struct();
        entry.centers   = ctrs;
        entry.clusters  = clusters;
        entry.alpha     = alpha;
        entry.c         = c;
        entry.score     = vfc.criterion_value(T, ctrs, clusters, alpha, opts.criterion);
        entry.criterion = upper(opts.criterion);
        entry.membership = [];
        entry.labels     = [];
        entry.intersections = sum(sum(N(ctrs, :), 1) > 1);
        buf{k} = entry;
    end
    results = vfc.rank_results([buf{:}], opts.max_results);
    for k = 1 : numel(results)
        results(k).membership = build_membership(T, results(k).centers, results(k).clusters, n);
        [~, results(k).labels] = max(results(k).membership, [], 2);
    end

    % ---------------------------------------------------------------------
    function search(depth, first, cover, power_sum)
        % cover(j) = number of chosen clusters that contain object j
        remaining = c - depth + 1;
        for q = first : numel(candidates) - remaining + 1
            t = candidates(q);
            new_sum = power_sum + powers(t);
            if new_sum > max_sum, continue; end
            if new_sum + (remaining - 1) * suffix_max(q) < n, continue; end
            if ~isinf(w)
                % no typical point may lie in another cluster
                if any(N(t, chosen(1 : depth-1))) || cover(t) > 0, continue; end
            end
            new_cover = cover + N(t, :);
            if ~isinf(w) && sum(new_cover > 1) > w, continue; end
            chosen(depth) = t;
            if depth == c
                if all(new_cover > 0)
                    found_centers(end+1, :) = chosen; %#ok<AGROW>
                end
            else
                search(depth + 1, q + 1, new_cover, new_sum);
            end
        end
    end
end

% =========================================================================
function U = build_membership(T, centers, clusters, n)
    c = numel(centers);
    U = zeros(n, c);
    for l = 1 : c
        members = clusters{l};
        U(members, l) = T(centers(l), members)';
    end
end

% =========================================================================
function opts = defaults(opts)
    if ~isfield(opts, 'max_intersections'), opts.max_intersections = 0;  end
    if ~isfield(opts, 'min_power'),   opts.min_power   = 1;     end
    if ~isfield(opts, 'max_power'),   opts.max_power   = 0;     end
    if ~isfield(opts, 'max_results'), opts.max_results = 200;   end
    if ~isfield(opts, 'criterion'),   opts.criterion   = 'F1';  end
end
